INSERT INTO the_full_order.tb_account_ingredient_master
 (account_id,ingredient_id,ingredient_name_raw,ingredient_name_std,category_name,base_unit,storage_type,needs_review,active_yn,user_id)
SELECT #{account_id},ingredient_id,ingredient_name_raw,ingredient_name_std,category_name,base_unit,storage_type,COALESCE(needs_review,0),'Y',#{user_id}
  FROM the_full_order.tb_ingredient_master WHERE ingredient_id=#{ingredient_id}
ON DUPLICATE KEY UPDATE active_yn='Y'
